Arguments: {"title":"Extract eBay UK listings from search results","cwd":null,"code":"const tabId = 1675924496;
const listings = await browserjs(tabId, () => {
  const items = [];
  // eBay search results usually use li.s-item
  const elements = document.querySelectorAll("ul.srp-results li.s-item, div.srp-river-results li.s-item");
  for (const el of elements) {
    const titleEl = el.querySelector(".s-item__title");
    const priceEl = el.querySelector(".s-item__price");
    const shippingEl = el.querySelector(".s-item__shipping, .s-item__logisticsCost");
    const linkEl = el.querySelector(".s-item__link");
    const subtitleEl = el.querySelector(".s-item__subtitle");
    const secondaryInfoEl = el.querySelector(".s-item__secondary-info");

    const title = titleEl ? titleEl.textContent.trim() : "";
    if (!title || title.toLowerCase().includes("shop on ebay") || title.toLowerCase().includes("sponsored")) continue;

    const price = priceEl ? priceEl.textContent.trim() : "";
    const shipping = shippingEl ? shippingEl.textContent.trim() : "";
    const link = linkEl ? linkEl.href : "";
    const subtitle = subtitleEl ? subtitleEl.textContent.trim() : "";
    const secondaryInfo = secondaryInfoEl ? secondaryInfoEl.textContent.trim() : "";

    items.push({
      title,
      price,
      shipping,
      link,
      subtitle,
      secondaryInfo
    });
  }
  return items;
});

console.log(`Found ${listings.length} listings:`);
console.log(JSON.stringify(listings.slice(0, 15), null, 2));
"}
