Arguments: {"cwd":null,"title":"Parse all eBay listings from page","code":"const tabId = 1675924496;
const parsedListings = await browserjs(tabId, () => {
  const items = [];
  const linkElements = Array.from(document.querySelectorAll("a[href*='/itm/']"));
  const seenIds = new Set();

  for (const a of linkElements) {
    const match = a.href.match(/\/itm\/(\d+)/);
    if (!match) continue;
    const itmId = match[1];
    if (itmId === "123456" || seenIds.has(itmId)) continue;

    let card = a;
    while (card && card.tagName !== "LI" && !card.classList.contains("s-item")) {
      card = card.parentElement;
    }
    if (!card) card = a.parentElement;

    const cardText = card ? card.innerText : "";
    if (!cardText || cardText.length < 20) continue;

    seenIds.add(itmId);

    // Parse the card lines
    const lines = cardText.split("\n").map(l => l.trim()).filter(Boolean);

    // Find title: usually the first non-"NEW LISTING" line
    let title = "";
    for (const l of lines) {
      if (l.includes("NEW LISTING")) {
        title = l.replace("NEW LISTING", "").trim();
        if (title) break;
      } else if (!l.includes("Opens in a new window") && !l.includes("Shop on eBay") && !l.includes("derosnopS")) {
        title = l;
        break;
      }
    }

    // Find price
    let price = "";
    let shipping = "Free delivery";
    let condition = "";
    let sellerInfo = "";

    for (const l of lines) {
      if (l.startsWith("£") && !price) {
        price = l;
      }
      if (l.toLowerCase().includes("delivery") || l.toLowerCase().includes("postage")) {
        shipping = l;
      }
      if (l.includes("Pre-owned") || l.includes("Brand new") || l.includes("Refurbished") || l.includes("For parts")) {
        condition = l;
      }
      if (l.includes("% positive") || l.includes("feedback")) {
        sellerInfo = l;
      }
    }

    items.push({
      id: itmId,
      url: `https://www.ebay.co.uk/itm/${itmId}`,
      title,
      price,
      shipping,
      condition,
      sellerInfo,
      fullText: cardText
    });
  }
  return items;
});

console.log(`Parsed ${parsedListings.length} listings.`);
// Save to tmp file
await write("tmp://ebay_parsed_listings.json", JSON.stringify(parsedListings, null, 2));
console.log("Saved to tmp://ebay_parsed_listings.json");
"}
