// Function to scrape listing details from an eBay item page
async function scrapeEbayItem(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  const details = await browserjs(tabId, () => {
