    const price = document.querySelector(".x-price-primary, .x-bin-price, [data-testid='x-price-primary']")?.innerText.trim() || "";
    const shipping = document.querySelector(".ux-labels-values--shipping, [data-testid='ux-labels-values--shipping']")?.innerText.trim() || "";
    const condition = document.querySelector(".x-item-condition-text, [data-testid='x-item-condition-text']")?.innerText.trim() || "";
    const conditionDesc = document.querySelector(".x-item-condition-dialog")?.innerText.trim() || "";
    const returns = document.querySelector(".ux-labels-values--returns, [data-testid='ux-labels-values--returns']")?.innerText.trim() || "";
    const seller = document.querySelector(".x-sellercard-atf__info__about-seller, [data-testid='x-sellercard-atf__info__about-seller']")?.innerText.trim() || "";

    // Description text (inside iframe or container)
    let desc = "";
    const descIframe = document.querySelector("#desc_ifr");
    if (descIframe && descIframe.contentDocument) {
      desc = descIframe.contentDocument.body.innerText.trim().slice(0, 500);
    } else {
      desc = document.querySelector(".d-item-description, #desc_div")?.innerText.trim().slice(0, 500) || "";
    }

    // Item specifics
    const specifics = {};
    document.querySelectorAll(".ux-layout-section-evo__item").forEach(item => {
      const label = item.querySelector(".ux-labels-values__labels")?.innerText.trim();
      const val = item.querySelector(".ux-labels-values__values")?.innerText.trim();
      if (label && val) specifics[label] = val;
    });

    // Photos count
    const photoCount = document.querySelectorAll(".ux-image-filmstrip-carousel-item, .filmstrip-thumbnail, [data-testid='ux-image-filmstrip-carousel-item']").length || document.querySelectorAll(".ux-image-carousel-item").length;

    // Auction vs Buy It Now
