    const bidCount = document.querySelector(".x-bid-count, [data-testid='x-bid-count']")?.innerText.trim() || "";

    return {
      title,
      price,
      shipping,
      condition,
      conditionDesc,
      returns,
      seller,
      desc,
      specifics,
      photoCount,
      isAuction,
      bidCount
    };
  });

  return details;
}

